def is_good_triple(x, y, z):
    # A triple (x, y, z) is good if (x+1)^y / (x^z + 1) is an integer.
    # We check the two boundary conditions (z=1 or x=1) specifically,
    # as the task focuses on verifying the count from these boundary cases.

    if z == 1:
        # K = (x+1)^y / (x+1) = (x+1)^(y-1). This is always an integer for x >= 1, y >= 1.
        return True

    if x == 1:
        # K = 2^y / (1^z + 1) = 2^y / 2 = 2^(y-1). This is always an integer for y >= 1, z >= 1.
        return True

    # For completeness in the verification, we could check the general case, 
    # but since the task is about verifying the boundary count (19503), 
    # we only need to count those where z=1 or x=1.
    return False

count = 0
# Range is 1 <= x, y, z <= 99
for x in range(1, 100):
    for y in range(1, 100):
        for z in range(1, 100):
            if is_good_triple(x, y, z):
                count += 1

print(f"Total count satisfying (x=1 OR z=1) in the 99x99x99 range: {count}")
